mapper.select:
select sdl.document_list_name as document_list_name from sys_document_list sdl WHERE sdl.enabled_flag = 'Y'
AND sdl.document_type = #{documentType}
AND sdl.document_category = #{documentCategory}
order by sdl.serial_number

select sdl.document_id , sdl.document_type , sdl.document_category , sdl.enabled_flag , sdl.system_flag , sdl.document_list_name , sdl.necessary_upload_flag, sdl.serial_number as serial_number from sys_document_list sdl
AND sdl.document_type = #{documentType}
AND sdl.document_category = #{documentCategory}
order by sdl.serial_number

SELECT *
FROM
    SYS_DOCUMENT_LIST ld
WHERE
    document_category = #{documentCategory}
  AND document_type = #{documentType}
  AND enabled_flag = #{enabledFlag}
